/**
 * Incorporate the Jsr160RequestDispatcher based on external configuration settings.
 * By default, the JSR160 dispatcher is off, but it can be activated again
 * through system properties or environment variables without altering the servlet setup.
 *
 * @param pConfig configuration to be modified
 */
private void integrateJsr160DispatcherBasedOnSettings(Configuration pConfig) {
    for (String configValue : new String[] { System.getProperty("org.jolokia.jsr160ProxyEnabled"), System.getenv("JOLOKIA_JSR160_PROXY_ENABLED") }) {
        if (configValue != null && (configValue.isEmpty() || Boolean.parseBoolean(configValue))) {
            String configuredDispatchers = pConfig.get(ConfigKey.DISPATCHER_CLASSES);
            pConfig.updateGlobalConfiguration(Collections.singletonMap(ConfigKey.DISPATCHER_CLASSES.getKeyValue(), (configuredDispatchers != null ? configuredDispatchers + "," : "") + "org.jolokia.jsr160.Jsr160RequestDispatcher"));
            return;
        }
    }
}

