/**
 * Conditionally adds the JsrRequestDispatcher based on external settings via system properties or environment variables.
 * By default, JSR160 dispatcher is not included, allowing for runtime activation without altering servlet configurations.
 *
 * @param pSettings Configuration object to be modified.
 */
private void includeJsr160DispatcherIfConfigured(Configuration pSettings) {
    String activeDispatchers = pSettings.get(ConfigKey.DISPATCHER_CLASSES);
    String jsr160DispatcherClassName = "org.jolokia.jsr160.Jsr160RequestDispatcher";
    if (activeDispatchers == null || !activeDispatchers.contains(jsr160DispatcherClassName)) {
        for (String parameter : new String[] { System.getProperty("org.jolokia.jsr160ProxyEnabled"), System.getenv("JOLOKIA_JSR160_PROXY_ENABLED") }) {
            if (parameter != null && (parameter.isEmpty() || Boolean.parseBoolean(parameter))) {
                {
                    pSettings.updateGlobalConfiguration(Collections.singletonMap(ConfigKey.DISPATCHER_CLASSES.getKeyValue(), (activeDispatchers != null ? activeDispatchers + "," : "") + jsr160DispatcherClassName));
                }
                return;
            }
        }
        if (activeDispatchers == null) {
            // Insert a placeholder dispatcher to prevent silent failures on JSR160 proxy requests when not enabled
            pSettings.updateGlobalConfiguration(Collections.singletonMap(ConfigKey.DISPATCHER_CLASSES.getKeyValue(), Jsr160ProxyNotEnabledByDefaultAnymoreDispatcher.class.getCanonicalName()));
        }
    }
}

