/**
 * Extracts the SOAP method name from an input stream of a SOAP request, without closing the stream.
 *
 * @param inputStream Source of the SOAP request data @nonnull
 * @param encodingSpec Character encoding specification of the input stream, null uses default system encoding @null
 * @return Extracted SOAP method name or null if the extraction fails @null
 */
private static String extractSoapOperation(InputStream inputStream, String encodingSpec) {
    try {
        // Use XMLInputFactory.newInstance() for compatibility with older Java versions (pre Java 1.6)
        final XMLInputFactory xmlFactory = XMLInputFactory.newInstance();
        final XMLStreamReader xmlStreamReader;
        if (encodingSpec != null) {
            xmlStreamReader = xmlFactory.createXMLStreamReader(inputStream, encodingSpec);
        } else {
            xmlStreamReader = xmlFactory.createXMLStreamReader(inputStream);
        }
        // Proceed with a simple parsing approach
        // Navigate to the first XML tag
        xmlStreamReader.nextTag();
        // Ensure the first tag is "Envelope"
        if (!"Envelope".equals(xmlStreamReader.getLocalName())) {
            LOG.debug("First tag in SOAP request is incorrect: '" + xmlStreamReader.getLocalName() + "' (expected 'Envelope')");
            // Parsing failure
            return null;
        }
        // Search for the "Body" tag within the document
        if (!locateChildTag(xmlStreamReader, "Body")) {
            LOG.debug("SOAP 'Body' tag not found in request");
            // Parsing failure
            return null;
        }
        xmlStreamReader.nextTag();
        // The current tag should represent the SOAP method name
        return "." + xmlStreamReader.getLocalName();
    } catch (final XMLStreamException e) {
        LOG.debug("Failed to parse SOAP request", e);
        // Parsing failure
        return null;
    }
}

